evidence:
on: [push]   # every branch, every push
jobs:
  build: { runs-on: ubuntu-latest, steps: [checkout, test, lint, docker-build-20min] }

pipeline {
  agent any
  stages {
    stage('Build') { steps { sh 'make build' } }
    stage('Test')  { steps { sh 'make test' } }
  }
}

pipeline {
  agent any
  stages { ... }
  post {
    always { junit 'reports/*.xml' }
    failure { echo 'notify the team' }
  }
}

def call(String channel, String msg) {
  slackSend channel: channel, message: msg
}

steps.config:
pipeline {
  agent any
  triggers { pollSCM('H/5 * * * *') }
  stages {
    stage('Build') { steps { sh 'npm run build' } }
    stage('Test') { steps { sh 'npm test' } }
    stage('Deploy') { steps { sh './deploy.sh prod' } }
  }
  post { failure { mail to: 'team@example.com' } }
}
